head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stockSearch.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gAcptNo;
scwin.gMainFormCd;
scwin.gFormVer;
scwin.gIsurCd;

//PF이익분배금 조회
scwin.vScrenID = 'ULDSTF15920.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    //  기간 from~ to  셋팅	
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FromDate.setValue($c.ut.cGetMinusMonth(vCurDate.substring(0, 4), vCurDate.substring(4, 6), vCurDate.substring(6, 8), 12)); // 한달전 날짜
    edt_ToDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜		

};
scwin.fn_CheckCond = function() {
    // 일자 체크
    if ($c.stf.getObjectValue(edt_FromDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if ($c.stf.getObjectValue(edt_ToDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }
    if ($c.stf.compareFromToDate2(edt_FromDate, edt_ToDate) == false) {
        return;
    }
    scwin.fn_Search();
};
scwin.fn_Search = function() {
    var url = "/DsclSearchPF.do?method=listPFproftDistr" + "&inputMessageId=PF_PROFT_DISTR_INOUT" + "&outputMessageId=PF_PROFT_DISTR_INOUT" + "&ISU_CD=" + $c.stf.getObjectValue(txb_IsuCd) + "&FROM_DATE=" + $c.stf.getObjectValue(edt_FromDate) + "&TO_DATE=" + $c.stf.getObjectValue(edt_ToDate) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    $c.cm.ShowWin(grd_Grid);
    dts_DsclList.DataID = encodeURI(url);
    dts_DsclList.reset();
};
scwin.btn_Search_onclick = function() {
    scwin.fn_CheckCond();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_Grid, "PF 이익금분배 목록", "", "8");
};
scwin.dts_DsclList_OnLoadError = function() {
    $c.stf.alert_error(dts_DsclList);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_DsclList_OnLoadCompleted = function(rowcount) {
    if (dts_DsclList.errorMsg) {
        $c.win.alert("OnLoadCompleted => " + dts_DsclList.errorMsg);
    } else {
        $c.cm.CloseWin(rowcount, grd_Grid); //조회완료시 LOADING 이미지 종료
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page); //총 건수

    }
};
scwin.img_Isu_Srh_onclick = function() {
    $c.stockSearch.JongmokSearch(txb_IsuCd, txb_IsuNm, SECUGRP_ID_PF, js_market, "A");
};
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_FromDate);
};
scwin.img_ToCal_onclick = function() {
    popUpCalendar2(edt_ToDate);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_FromDate, edt_ToDate);
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
    scwin.fn_CheckCond();
    $c.cm.fn_jongMok(txb_IsuCd, txb_IsuNm, SECUGRP_ID_PF, "0", "A");
};
scwin.Grd_jong_mok_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_jongMok_set();
    }
};
scwin.Grd_jong_mok_OnDblClick = function(row, colid) {
    $c.cm.fn_jongMok_set();
};
scwin.Grd_jong_mok_OnClick = function(row, colid) {
    Grd_jong_mok.style.display = "";
};
scwin.Grd_jong_mok_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_jong_mok_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_jong_mok.style.display = "none";
};
scwin.MxDataSet_jong_mok_OnFilter = function(row) {
    if (skw != "") {
        f1 = MxDataSet_jong_mok.getCellData(row, "ISU_KOR_ABBRV");
        f2 = MxDataSet_jong_mok.getCellData(row, "ISU_CD");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.Grd_jong_mok_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_jongMok_set();
    }
};
scwin.Grd_jong_mok_OnDblClick = function(row, colid) {
    $c.cm.fn_jongMok_set();
};
scwin.Grd_jong_mok_OnClick = function(row, colid) {
    Grd_jong_mok.style.display = "";
};
scwin.Grd_jong_mok_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_jong_mok_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_jong_mok.style.display = "none";
};
scwin.txb_IsuCd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_jong_mok.style.display = "none";
    }
    if (txb_IsuCd.getValue() == "") {
        txb_IsuNm.setValue("");
    }
};
scwin.txb_IsuCd_onfocus = function() {
    Grd_jong_mok.style.display = "none";
};
scwin.txb_IsuCd_onkeyup = function() {
    if (txb_IsuCd.getValue() == "") {
        Grd_jong_mok.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_jong_mok.focus();
        } else {
            $c.cm.fn_jongMok_nm(window.event.keyCode);
            //txtTest.value = window.event.keyCode;

        }
    }
};
scwin.MxDataSet_jong_mok_OnFilter = function(row) {
    if (skw != "") {
        f1 = MxDataSet_jong_mok.getCellData(row, "ISU_KOR_ABBRV");
        f2 = MxDataSet_jong_mok.getCellData(row, "ISU_CD");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
